package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
// 计算差值数组
func getDiff(word string) []int {
    diff := make([]int, len(word)-1)
    for i := 0; i < len(word)-1; i++ {
        diff[i] = int(word[i+1]) - int(word[i])
    }
    return diff
}
​
func solve(words []string) string {
    diff0 := getDiff(words[0])
    diff1 := getDiff(words[1])
    // 相同寻找下一个与当前不同的字符串
    if equal(diff0, diff1) {
        for i := 2; i < len(words); i++ {
            if !equal(diff0, getDiff(words[i])) {
                return words[i]
            }
        }
    }
    // 不相同 寻找下一个字符串 看与哪个不一致
    if equal(diff0, getDiff(words[2])) {
        return words[1]
    }
    return words[0]
}
​
func equal(a, b []int) bool {
    if len(a) != len(b) {
        return false
    }
    for i := range a {
        if a[i] != b[i] {
            return false
        }
    }
    return true
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    scanner.Scan()
    parts := strings.Split(scanner.Text(), " ")
​
    m, err1 := strconv.Atoi(parts[0])
    n, err2 := strconv.Atoi(parts[1])
    _ = m
    _ = n
​
    if err1 != nil || err2 != nil {
        return
    }
​
    scanner.Scan()
    words := strings.Split(scanner.Text(), " ")
​
    fmt.Println(solve(words))
}
